ROOT=Path(__file__).resolve().parents[3]; D=Path(__file__).resolve().parent
PATH=ROOT/'protocols/gastrointestinal/00642-lutetium-177-oxodotreotide-lutathera-therapy.json'
p=json.loads((D/'protocol-before'/PATH.name).read_text())
