I={}; R=[]
def inp(k,label,typ='number',**kw):
 I[k]={'label':label,'type':typ,'required':False,'input_role':'decision',**kw}
 if typ=='number':I[k].setdefault('min',0);I[k].setdefault('step',0.01)
 if typ=='boolean':I[k].setdefault('demo_value',False)
def sel(k,label,opts,**kw):inp(k,label,'select',options=[{'value':v,'label':l} for v,l in opts],**kw)
def c(k,op,v=None):return {'field':k,'operator':op,**({'value':v} if v is not None else {})}
def all_(*x):return {'all':list(x)}
def any_(*x):return {'any':list(x)}
def rule(id,when,typ,msg,page,ema=False,**kw):
 a={'type':typ,'components':['lutetium_177_oxodotreotide'],'message':msg,'recommendation':msg,**kw}
 R.append({'id':id,'priority':20,'when':when,'action':a,'source':{'document':'EMA Lutathera product information, updated 14 August 2026' if ema else 'NCCP 00642 v2, 27 May 2025','url':EMA if ema else N,'page':str(page)},'explanation':msg})
sel('prrt_assessment_stage','PRRT assessment stage',[('baseline','Before first infusion'),('on_treatment','During PRRT / before a later infusion')],ui_section='treatment_context',always_show=True)
B=c('prrt_assessment_stage','==','baseline'); T=c('prrt_assessment_stage','==','on_treatment')
inp('age_years','Age (years)',step=1)
sel('net_grade','NET differentiation / grade',[('well_differentiated_g1_g2','Well differentiated G1 or G2'),('other','G3, poorly differentiated or another diagnosis'),('unknown','Not confirmed')])
for k,label in [('gep_net','Gastroenteropancreatic NET confirmed'),('progressive_unresectable_or_metastatic','Progressive unresectable or metastatic disease confirmed'),('progressed_on_standard_octreotide','Progression on standard octreotide confirmed'),('curative_surgery_candidate','Candidate for curative surgery'),('specialist_mdm_and_licensed_service_plan','NET specialist / MDM and authorised PRRT service plan confirmed'),('hypersensitivity','Known hypersensitivity to Lutathera or excipients'),('pregnancy','Pregnant or pregnancy suspected'),('breastfeeding','Breastfeeding'),('pregnancy_excluded_if_relevant','Pregnancy excluded by appropriate test where relevant'),('prior_marrow_rt_over_25_percent','Previous external beam radiation involving more than 25% of marrow'),('nyha_iii_iv_heart_failure','NYHA III or IV heart failure'),('other_organ_function_concern','Other renal, hepatic, cardiac or marrow eligibility concern')]:inp(k,label,'boolean')
sel('sstr_imaging','Somatostatin-receptor imaging',[('uptake_at_least_liver','Tumour receptor uptake at least normal liver uptake'),('negative_or_mixed','Receptor-negative or mixed visceral lesions'),('unconfirmed','Imaging / adequate uptake not confirmed')])
inp('fixed_long_acting_ssa_weeks','Weeks on fixed-dose long-acting SSA before PRRT eligibility assessment',unit='weeks')
inp('ecog','ECOG performance status',max=4,step=1)
rule('PRRT_AGE',c('age_years','<',18),'consultant_review','The NCCP adult pathway requires age at least 18 years; do not apply it automatically to a paediatric patient.',1)
rule('PRRT_GRADE',c('net_grade','!=','well_differentiated_g1_g2'),'consultant_review','This NCCP indication is well-differentiated G1/G2 disease; other or unconfirmed histology requires a separately justified specialist pathway.',1)
for k in ['gep_net','progressive_unresectable_or_metastatic','progressed_on_standard_octreotide','specialist_mdm_and_licensed_service_plan']:
 rule('PRRT_ELIGIBILITY_'+k.upper(),c(k,'==',False),'consultant_review','Required NCCP eligibility/service criterion not confirmed: '+I[k]['label']+'. Confirm with the NET specialist before treatment.','1–2')
rule('PRRT_SSTR',c('sstr_imaging','!=','uptake_at_least_liver'),'consultant_review','Confirm receptor-positive tumour imaging with uptake at least normal liver. Receptor-negative or mixed visceral lesions are not a routine Lutathera pathway.','2,7',True)
rule('PRRT_SSA_PRETREATMENT',c('fixed_long_acting_ssa_weeks','<',12),'consultant_review','NCCP eligibility specifies at least 12 weeks of fixed-dose long-acting SSA treatment before PRRT.',1)
rule('ECOG_OUTSIDE_USUAL_SOURCE_RANGE',c('ecog','>',2),'consultant_review','NCCP eligibility specifies ECOG 0–2.',2)
for k in ['hypersensitivity','pregnancy','breastfeeding','curative_surgery_candidate']:
 rule('PRRT_EXCLUSION_'+k.upper(),c(k,'==',True),'contraindicated','Do not administer within this pathway: '+I[k]['label']+'. Confirm the appropriate alternative with the specialist.',2)
rule('PRRT_PREGNANCY_NOT_EXCLUDED',c('pregnancy_excluded_if_relevant','==',False),'contraindicated','Where pregnancy is possible, it must be excluded using an appropriate validated test before Lutathera.','7,12',True)
for k in ['prior_marrow_rt_over_25_percent','nyha_iii_iv_heart_failure','other_organ_function_concern']:
 rule('PRRT_CAUTION_'+k.upper(),c(k,'==',True),'consultant_review','Specialist benefit–risk review and monitoring required: '+I[k]['label']+'. Consider amino-acid volume load in severe heart failure.',2)
# Exact renal measurements; legacy source-specific bands remain interpretable for retained forms.
inp('crcl_ml_min','Current creatinine clearance (Cockcroft–Gault, actual body weight)',unit='mL/min',demo_value=80,help='Use the source-specified Cockcroft–Gault creatinine clearance with actual body weight; do not substitute indexed eGFR.')
inp('baseline_crcl_ml_min','Pretreatment baseline creatinine clearance (same method)',unit='mL/min',min=0.01)
