for k,l,fields in [('prrt_crcl_ratio','Current / baseline creatinine clearance',['crcl_ml_min','baseline_crcl_ml_min']),('prrt_creatinine_ratio','Current / baseline serum creatinine',['creatinine_umol_l','baseline_creatinine_umol_l'])]:
 inp(k,l,derived_value={'operation':'ratio','fields':fields},ui_hidden=True,help='Calculated from direct measurements; a supplied ratio is never trusted.')
sel('lutathera_renal_band','Legacy Lutathera renal category (use exact CrCl when available)',[('ge40','CrCl ≥40 mL/min'),('30_39','CrCl 30 to <40 mL/min'),('lt30','CrCl <30 mL/min'),('dialysis','Dialysis')],renal_input={'mode':'protocol_specific_band','exact_value_required':False},visible_when=all_(c('prrt_assessment_stage','==','baseline'),c('prrt_assessment_stage','==','on_treatment')))
renal_low=any_(c('crcl_ml_min','<',30),c('lutathera_renal_band','==','lt30'))
