renal_bad=any_(c('lutathera_renal_band','in',['30_39','lt30']),c('crcl_ml_min','<',40),c('prrt_creatinine_ratio','>=',1.4),c('prrt_crcl_ratio','<=',.6))
rule('PRRT_RENAL_LT30',renal_low,'contraindicated','CrCl below 30 mL/min is a formal contraindication; do not administer.','2,4')
rule('PRRT_DIALYSIS_REVIEW',c('lutathera_renal_band','==','dialysis'),'consultant_review','End-stage renal disease / dialysis has not been studied in the routine source pathway. No automatic dose; specialist radionuclide and renal review is required. CrCl below 30 mL/min is contraindicated.',4)
rule('PRRT_BASELINE_RENAL_30_39',all_(B,renal_mid),'consultant_review','Baseline CrCl 30 to below 40 mL/min: treatment is not recommended. This is distinct from the formal below-30 contraindication; do not infer a reduced initial activity.',4)
rule('PRRT_RENAL_STAGE_UNKNOWN',all_(renal_mid,c('prrt_assessment_stage','missing')),'consultant_review','CrCl 30 to below 40 requires assessment stage: baseline treatment is not recommended; treatment-emergent renal toxicity requires withholding. Do not automatically treat.', '4–5')
rule('PRRT_RENAL_TOXICITY_HOLD',all_(T,renal_bad),'withhold','Treatment-emergent renal toxicity: CrCl <40, serum creatinine rise at least 40%, or CrCl fall at least 40% from baseline. Withhold until resolution or return to baseline; use the specialist recovery/recurrence pathway.',5)
inp('lutathera_renal_toxicity','Clinician-confirmed treatment-emergent renal toxicity','boolean')
rule('PRRT_RENAL_CONFIRMED_HOLD',c('lutathera_renal_toxicity','==',True),'withhold','Clinician-confirmed renal toxicity: withhold until resolution or return to baseline; assess episode history and elapsed dosing interval before considering reduced activity.',5)
rule('PRRT_RENAL_RELATIVE_STAGE_UNKNOWN',all_(any_(c('prrt_creatinine_ratio','>=',1.4),c('prrt_crcl_ratio','<=',.6)),c('prrt_assessment_stage','missing')),'consultant_review','A relative renal toxicity threshold is reached. Confirm pretreatment baseline and treatment stage; a normal absolute CrCl alone does not establish renal recovery.',5)
# Marrow values; grade must not be invented at printed boundaries.
for k,l,u in [('haemoglobin_g_dl','Haemoglobin','g/dL'),('platelets_x10e9_l','Platelets','×10⁹/L'),('anc_x10e9_l','Absolute neutrophil count','×10⁹/L'),('leucocytes_x10e9_l','Total white cell count','×10⁹/L')]:inp(k,l,unit=u)
inp('life_threatening_anaemia','Life-threatening anaemia','boolean')
inp('isolated_lymphopenia','Low total white cells / other haematological toxicity is solely lymphopenia','boolean')
for id,cond,msg,page in [('HB',any_(c('haemoglobin_g_dl','<',8),c('life_threatening_anaemia','==',True)),'Hb <8 g/dL or life-threatening anaemia',4),('PLATELETS',c('platelets_x10e9_l','<',75),'platelets <75 ×10⁹/L',3),('ANC',c('anc_x10e9_l','<',1),'ANC <1 ×10⁹/L', '3–4; EMA p4')]:
 rule('PRRT_'+id+'_HOLD',cond,'withhold','Withhold PRRT for '+msg+'. Confirm severity, recovery, prior episode and treatment timing with the specialist before any resumption.',page)
rule('PRRT_PLATELET_75_BOUNDARY',c('platelets_x10e9_l','==',75),'consultant_review','At platelets exactly 75 ×10⁹/L, NCCP Table 3 prints grade 2 as 50–75 while the caution and EMA use <75. Confirm grading with the specialist; no automatic treatment or restart.', '2–3; EMA p4',dose_calculation='specialist_review')
rule('PRRT_WBC_LOW',all_(c('leucocytes_x10e9_l','<',2),c('isolated_lymphopenia','==',False)),'consultant_review','Leucocytes <2 ×10⁹/L not solely due to lymphopenia: treatment is not recommended without specialist review; inspect differential and marrow reserve.',2)
rule('PRRT_WBC_CAUSE_UNKNOWN',all_(c('leucocytes_x10e9_l','<',2),c('isolated_lymphopenia','missing')),'consultant_review','Leucocytes <2 ×10⁹/L: establish whether this is isolated lymphopenia. The exception cannot be assumed from an absent differential.',2)
