for k,l,u in [('bilirubin_ratio_uln','Bilirubin / laboratory upper limit of normal','×ULN'),('albumin_g_l','Albumin','g/L'),('inr','INR','ratio')]:inp(k,l,unit=u)
sel('lutathera_hepatic_band','Legacy Lutathera hepatic category',[('none_mild_moderate','None, mild or moderate'),('severe','Severe / bilirubin >3×ULN')],visible_when=all_(c('prrt_assessment_stage','==','baseline'),c('prrt_assessment_stage','==','on_treatment')))
hep=any_(c('bilirubin_ratio_uln','>',3),all_(c('albumin_g_l','<',30),c('inr','>',1.5)),c('lutathera_hepatic_band','==','severe'))
