rule('PRRT_HEPATIC_HOLD',all_(T,hep),'withhold','Treatment-emergent hepatotoxicity at the source thresholds: withhold until resolution or return to baseline; assess reduced-activity, recurrence and interval criteria.',5)
inp('lutathera_hepatic_toxicity','Clinician-confirmed treatment-emergent hepatic toxicity','boolean')
