inp('other_toxicity_grade','Other CTCAE adverse reaction grade (exclude the separately entered renal/hepatic/count pathways)',max=4,step=1)
rule('PRRT_OTHER_G34_HOLD',all_(c('other_toxicity_grade','>=',3),c('isolated_lymphopenia','==',False)),'withhold','Other grade 3/4 adverse reaction: withhold until grade 0–2; assess episode history and timing. Isolated lymphopenia is excluded from this automatic dose-modification pathway.',5)
rule('PRRT_OTHER_LYMPHOPENIA_CONTEXT',all_(c('other_toxicity_grade','>=',3),c('isolated_lymphopenia','missing')),'consultant_review','For other grade 3/4 toxicity confirm it is not solely lymphopenia before applying the PRRT interruption pathway.','5; EMA p5')
