inp('prrt_reduced_infusion_tolerated','After a 3,700 MBq infusion, no qualifying dose-modifying toxicity recurred','boolean')
domains={'platelet':('grade 2–4 thrombocytopenia','3'),'anaemia':('grade 3–4 anaemia','4'),'neutrophil':('grade 3–4 neutropenia','3–4'),'renal':('renal toxicity','5'),'hepatic':('hepatotoxicity','5'),'other':('other grade 3–4 toxicity, excluding isolated lymphopenia','5')}
for k,(label,page) in domains.items():
 episode=k+'_toxicity_episode_count'; recovery=k+'_toxicity_recovery'
 inp(episode,'Number of qualifying '+label+' episodes',step=1,help='0 means none. Include a prior episode even if current measurements have recovered.')
 sel(recovery,'Recovery from '+label,[('active','Still above the source recovery threshold'),('recovered','Recovery threshold confirmed by specialist')],visible_when=c(episode,'>=',1),help='Platelets: grade 0–1; anaemia/neutropenia/other: grade 0–2; renal/hepatic: resolution or return to baseline.')
 rule('PRRT_'+k.upper()+'_RECURRENCE',c(episode,'>=',2),'permanently_discontinue','Recurrent '+label+': permanently discontinue Lutathera according to the source, even if the current measurement has recovered.',page)
