 rule('PRRT_'+k.upper()+'_LATE_INTERVAL',all_(c(episode,'>=',1),c('weeks_since_last_prrt','>',16)),'permanently_discontinue','Qualifying '+label+' requiring a dosing interval beyond 16 weeks: permanently discontinue (EMA). NCCP tables use “treatment delay of 16 weeks or longer”; do not restart beyond this limit.','4–5',True)
