rule('PRRT_RADIATION_PLAN',c('radiation_discharge_plan_confirmed','==',False),'consultant_review','An individual radiation-protection, contact, toilet/waste, travel and discharge plan is required from the licensed service. General advice does not determine safe discharge.','9; patient leaflet48–49',True)
inp('days_since_long_acting_ssa','Days since last long-acting somatostatin analogue',unit='days')
inp('hours_since_short_acting_ssa','Hours since last short-acting somatostatin analogue',unit='hours')
