rule('PRRT_SHORT_SSA_TIMING',c('hours_since_short_acting_ssa','<',24),'withhold','Short-acting SSA within 24 hours before PRRT requires specialist timing review. Do not automatically administer PRRT or stop necessary symptom control without a service plan.',6)
rule('PRRT_CRISIS_RISK',c('carcinoid_crisis_risk','==',True),'consultant_review','Functioning NETs, high burden or poor syndrome control increase hormonal-crisis risk. Confirm prevention/rescue and whether overnight observation is appropriate.','7; EMA p9')
rule('PRRT_CRISIS_EMERGENCY',c('suspected_hormonal_crisis','==',True),'withhold','Suspected hormonal/carcinoid crisis: urgent clinical management under the service emergency protocol. This assessment does not calculate crisis medicines.','7; EMA p9')
rule('PRRT_SEVERE_INFUSION_REACTION',c('severe_infusion_hypersensitivity','==',True),'withhold','Stop the ongoing Lutathera infusion immediately and institute urgent hypersensitivity management; specialist review is required before any further exposure.','8',True)
rule('PRRT_STEROID_INTERACTION',c('repeated_high_dose_glucocorticoids','==',True),'consultant_review','Repeated high-dose glucocorticoids can reduce SSTR2 expression. Review receptor uptake and necessity. Corticosteroids are not first-line preventive antiemetics; any rescue dose and timing require the specialist plan.','12',True)
rule('PRRT_INTERCURRENT_ILLNESS',c('intercurrent_illness_increasing_risk','==',True),'withhold','Resolve or stabilise an intercurrent illness that increases PRRT risk before resuming. Confirm with the specialist.','5',True)
inp('weeks_since_major_surgery','Weeks since major surgery',unit='weeks',visible_when=c('recent_major_surgery','==',True))
rule('PRRT_MAJOR_SURGERY_HOLD',all_(c('recent_major_surgery','==',True),c('weeks_since_major_surgery','<',12)),'withhold','The EMA SmPC requires PRRT to be withheld for 12 weeks after major surgery; confirm healing and specialist reassessment.','5',True)
rule('PRRT_MAJOR_SURGERY_UNKNOWN',all_(c('recent_major_surgery','==',True),c('weeks_since_major_surgery','missing')),'consultant_review','Record time since major surgery: EMA requires a 12-week postoperative interruption.','5',True)

for k,d in I.items():
 d.setdefault('demo_value',d['options'][0]['value'] if d['type']=='select' else False if d['type']=='boolean' else max(1,d.get('min',0)))
 if d.get('derived_value'):
  d['visible_when']={'all':[{'field':'prrt_assessment_stage','operator':'==','value':'baseline'},{'field':'prrt_assessment_stage','operator':'==','value':'on_treatment'}]}
  d.pop('ui_hidden',None)
p['input_definitions']=I;p['rule_engine']['rules']=R;p['required_inputs']=[]
p['metadata'].update(source_document_pages=7,encoding_version='0.84.37',sactcheck_encoding_version='0.84.37',clinical_audit_release='0.84.37',review_date='2030-05-27')
