p['metadata']['organ_function_reconciliation'].update(release='0.84.37',checked_date='2026-11-05',resolution='source_specific_rules_with_explicit_specialist_conflicts',note='Current NCCP v2 and EMA 14 August 2026 reconciled; exact renal measurements and derived relative change, distinct baseline hepatic review and on-treatment hold. Independent review pending.')
