p['metadata']['validation']['audit_release']='0.84.37'
p['metadata']['validation']['rule_level_source_reconciliation_status']='source_reconciled_v08437_independent_review_pending'
p['metadata']['schedule_summary']='Four specialist PRRT infusions of 7,400 MBq IV, normally eight weeks apart. Antiemetic precedes four-hour renal-protective amino acids; SSA timing and radiation discharge are service-prescribed. Toxicity may require reduced activity, delay or stopping.'
p['eligibility']=['Adults with progressive unresectable/metastatic well-differentiated G1/G2 SSTR-positive GEP-NET; receptor imaging uptake at least normal liver (EMA).','NCCP specifies progression on standard octreotide and at least 12 weeks on fixed-dose long-acting SSA.','ECOG 0–2; adequate renal, hepatic, marrow and cardiac function; individual NET MDM/specialist plan and licensed PRRT service.']
p['exclusions']=['Known hypersensitivity to Lutathera or excipients.','Curative-surgery candidates are outside this NCCP indication.','CrCl below 30 mL/min is contraindicated; baseline CrCl 30 to below 40 is not recommended, a distinct category.','Established/suspected pregnancy or pregnancy not excluded where relevant; breastfeeding must be stopped according to specialist advice.']
p['monitoring']=['Baseline FBC, renal and liver profile, cardiac ECHO or MUGA, and pregnancy test where relevant (NCCP p3).','FBC, renal and liver tests at least once 2–4 weeks before each infusion AND shortly before administration; every two weeks between infusions (NCCP p3).','After the final infusion: FBC/renal/liver tests every four weeks for at least three months, then every three months for the following year (NCCP p3). EMA specifies every six months thereafter; the Irish regimen is more intensive and is retained.','Serum creatinine and Cockcroft–Gault CrCl at baseline, during treatment and for at least the first year afterwards. Include albumin and INR for the hepatic criterion.','Potassium before each amino-acid infusion; correct hyperkalaemia and repeat before infusion if previously clinically significant. Monitor vital signs; ECG before discharge where indicated by the hyperkalaemia pathway (EMA p11).','Disease imaging and tumour markers are directed by the consultant treatment plan; no universal fixed scan or marker timetable is assumed.','Monitor delayed marrow effects including MDS/acute leukaemia and renal injury; source follow-up is not ended when the four-cycle wallet is complete.']
p['dose_modifications']=['Structured rules assess indication, source-specific renal/hepatic/marrow thresholds, relative renal change, recovery, recurrence and timing. All PRRT administration and activity changes remain specialist decisions.','First qualifying toxicity: withhold to the source recovery threshold; source resumption level is 3,700 MBq. If that reduced infusion does not produce qualifying toxicity, a subsequent infusion may return to 7,400 MBq. No numerical activity is automatically authorised.','Recurrent qualifying toxicity permanently stops treatment. A toxicity-related interval beyond 16 weeks stops treatment under EMA. At exactly 16 weeks, NCCP wording (delay ≥16 weeks) conflicts with its own schedule and EMA (interval beyond 16 weeks); specialist reconciliation is explicitly required.','Platelets exactly 75 ×10⁹/L have a printed NCCP Table 3 versus caution/EMA boundary conflict. The tool requests review instead of inferring grade/restart. ANC <1 ×10⁹/L follows the continuous EMA band, avoiding the NCCP printed 0.99-to-1.0 gap.','The generic eGFR/CrCl 30–49 band has been removed; use actual-body-weight Cockcroft–Gault values. Missing baseline measurements never imply no relative renal change.']
p['supportive_care'].update(emetogenic_risk='moderate',script_id='nccp-prrt-v08437',mapping_source='NCCP 00642 v2 pp5–7; EMA Lutathera SmPC 4.2/4.4/4.5 (14 August 2026)',mapping_source_url=N,mapping_basis='PRRT-specific antiemetic and renal-protection pathway. Do not use a generic dexamethasone-containing moderate-risk prescription.',mapping_confidence='high',specialist_plan_required=True)
p['supportive_care']['supportive_medications_label']='PRRT-specific antiemetic and amino-acid protection plan'
p['supportive_care']['regimen_specific_instructions']=['5-HT3 antagonist at least 30 minutes before amino-acid infusion; additional antiemetics per solution/service. Corticosteroids are not first-line preventive antiemetics.','L-lysine/L-arginine renal protection IV over four hours beginning 30 minutes before PRRT. Do not reduce amino-acid dose when PRRT activity is reduced.','Standard preferred solution: L-lysine HCl 25 g plus L-arginine HCl 25 g in 1 L; prescribed/prepared by the authorised service. Check potassium and fluid/heart-failure risks.','Long-acting SSA should be avoided in the preceding 30 days; short-acting SSA until 24 hours before only. NCCP permits long-acting SSA 24 hours after, or the same evening after day-case PRRT; follow the written service plan.','Repeated high-dose glucocorticoids may downregulate SSTR2. EMA rescue antiemetic steroid is not given before PRRT or within one hour after infusion ends.','Carcinoid/hormonal crisis prevention and emergency treatment, hydration, radiation protection and discharge restrictions follow the licensed service plan.']
p['treatment']['components']=[{'drug': 'lutetium_177_oxodotreotide', 'dose': '7400 MBq', 'route': 'IV infusion', 'day': 1, 'note': 'Over approximately 30–40 minutes; every 56 days for four administrations. Renal-protective amino-acid infusion begins 30 minutes before PRRT and runs for four hours. Reference schedule only; activity, interval changes and administration require the authorised PRRT service.', 'source': {'document': 'NCCP 00642 v2, 27 May 2025', 'url': 'https://healthservice.hse.ie/documents/6683/642_v2_Lutetium_Lu177_oxodotretide.pdf', 'page': '1'}}]
